import"./chunk-VC46IEJQ.js";var e=(a,o)=>({en:a,zh:o}),t=(a,o,r,n,h,i,d,l,s)=>({name:a,desc:o,tour:r,...s?{spoiler:s}:{},source:{confidence:n,refs:h,book:i,unknown:d,interpretation:l}}),w={id:"harrenhal",intro:e("The largest castle in Westeros, raised on the northern shore of the God's Eye by Harren the Black. It was finished just as Aegon the Conqueror landed, and his dragon's fire melted the tops of its five immense towers. What remains is a vast, half-empty ruin of black stone.","\u7EF4\u65AF\u7279\u6D1B\u6700\u5927\u7684\u57CE\u5821\uFF0C\u7531\u9ED1\u5FC3\u8D6B\u4F26\u5EFA\u4E8E\u795E\u773C\u6E56\u5317\u5CB8\u3002\u57CE\u5821\u843D\u6210\u4E4B\u65F6\uFF0C\u6070\u9022\u5F81\u670D\u8005\u4F0A\u803F\u767B\u9646\uFF1B\u5DE8\u9F99\u7684\u70C8\u7130\u7194\u584C\u4E86\u4E94\u5EA7\u5DE8\u5854\u7684\u5854\u9876\u3002\u5982\u4ECA\u7559\u4E0B\u7684\uFF0C\u662F\u4E00\u5EA7\u7A7A\u65F7\u5927\u534A\u7684\u9ED1\u77F3\u5E9F\u589F\u3002"),notes:e("From the novels: the five named towers of black stone with melted tops, enormous walls, the Hall of a Hundred Hearths, the godswood, the bear pit, the baths and the lake. Invented here: the plan, where each tower stands, the tower shapes in detail, every distance and the surrounding country.","\u51FA\u81EA\u5C0F\u8BF4\uFF1A\u4E94\u5EA7\u6709\u540D\u5B57\u7684\u9ED1\u77F3\u5DE8\u5854\u53CA\u5176\u7194\u6BC1\u7684\u5854\u9876\u3001\u5DE8\u5927\u7684\u57CE\u5899\u3001\u767E\u7089\u5385\u3001\u795E\u6728\u6797\u3001\u718A\u5751\u3001\u6D74\u573A\u4E0E\u6E56\u6CCA\u3002\u672C\u573A\u666F\u81EA\u884C\u8BBE\u8BA1\uFF1A\u6574\u4F53\u5E73\u9762\u3001\u5404\u5854\u4F4D\u7F6E\u3001\u5854\u697C\u7EC6\u90E8\u9020\u578B\u3001\u4E00\u5207\u8DDD\u79BB\u53CA\u5468\u8FB9\u5730\u8C8C\u3002"),tour:["walls-and-gate","kingspyre-tower","widows-tower","tower-of-dread","wailing-tower","tower-of-ghosts","hall-of-hundred-hearths","godswood","bear-pit","god-s-eye"],sources:[{ref:"acok",checked:"memory",note:e("Arya's chapters at Harrenhal supply most of the castle's texture: the towers, the vaults under the Wailing Tower, the great hall and the godswood. Recalled, not re-read.","\u827E\u8389\u4E9A\u5728\u8D6B\u4F26\u5821\u7684\u7AE0\u8282\u63D0\u4F9B\u4E86\u57CE\u5821\u7684\u5927\u90E8\u5206\u8D28\u611F\uFF1A\u5404\u5EA7\u5854\u697C\u3001\u54C0\u568E\u5854\u4E0B\u7684\u5730\u7A96\u3001\u5927\u5385\u4E0E\u795E\u6728\u6797\u3002\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002")},{ref:"asos",checked:"memory",note:e("The bear pit and the baths appear in Jaime's and Brienne's chapters; recalled.","\u718A\u5751\u4E0E\u6D74\u573A\u51FA\u73B0\u5728\u8A79\u59C6\u4E0E\u5E03\u857E\u59AE\u7684\u7AE0\u8282\u4E2D\uFF1B\u51ED\u8BB0\u5FC6\u3002")},{ref:"twoiaf",checked:"memory",note:e("Harren the Black's forty years of building, the burning by Aegon's dragon and the castle's later ill luck; recalled.","\u9ED1\u5FC3\u8D6B\u4F26\u56DB\u5341\u5E74\u7684\u8425\u5EFA\u3001\u4F0A\u803F\u7684\u5DE8\u9F99\u711A\u57CE\uFF0C\u4EE5\u53CA\u57CE\u5821\u6B64\u540E\u7684\u5384\u8FD0\uFF1B\u51ED\u8BB0\u5FC6\u3002")},{ref:"awoiaf",checked:"search-snippet",note:e("Search summaries of the wiki and concordance confirm the five tower names, black stone, the shortest tower being half again the height of Winterfell's tallest, Kingspyre as the tallest with the castellan's chambers, a stone bridge from the Widow's Tower to Kingspyre with a dungeon below, vaults under the Wailing Tower, and only about thirty-three to thirty-five hearths in the great hall. Pages not fetched.","\u7EF4\u57FA\u4E0E\u8BCD\u6761\u7D22\u5F15\u7684\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF1A\u4E94\u5854\u4E4B\u540D\u3001\u9ED1\u8272\u77F3\u6750\u3001\u6700\u77EE\u7684\u5854\u4E5F\u6BD4\u4E34\u51AC\u57CE\u6700\u9AD8\u7684\u5854\u9AD8\u51FA\u4E00\u534A\u3001\u738B\u711A\u5854\u6700\u9AD8\u4E14\u4E3A\u4EE3\u7406\u57CE\u4E3B\u5C45\u6240\u3001\u5BE1\u5987\u5854\u6709\u77F3\u6865\u901A\u5F80\u738B\u711A\u5854\u4E14\u5854\u4E0B\u6709\u5730\u7262\u3001\u54C0\u568E\u5854\u4E0B\u6709\u5730\u7A96\uFF0C\u4EE5\u53CA\u5927\u5385\u5B9E\u9645\u53EA\u6709\u4E09\u5341\u4E09\u81F3\u4E09\u5341\u4E94\u5EA7\u58C1\u7089\u3002\u9875\u9762\u672A\u6293\u53D6\u3002")}],landmarks:{"tower-of-dread":t(e("Tower of Dread","\u6050\u60E7\u5854"),e("One of the five great towers, its top slumped by dragonfire like melted wax.","\u4E94\u5EA7\u5DE8\u5854\u4E4B\u4E00\uFF0C\u5854\u9876\u88AB\u9F99\u7130\u7194\u584C\uFF0C\u5B9B\u5982\u6D41\u6DCC\u7684\u8721\u6CEA\u3002"),e("Even the smallest tower here is half again as tall as Winterfell's tallest.","\u8FD9\u91CC\u6700\u77EE\u7684\u5854\uFF0C\u4E5F\u6BD4\u4E34\u51AC\u57CE\u6700\u9AD8\u7684\u5854\u9AD8\u51FA\u4E00\u534A\u3002"),"medium",["acok","awoiaf"],e("One of the five named towers, melted at the top; reference summaries place it near the middle bailey and the mews.","\u4E94\u5EA7\u6709\u540D\u5B57\u7684\u5854\u697C\u4E4B\u4E00\uFF0C\u5854\u9876\u7194\u6BC1\uFF1B\u53C2\u8003\u6458\u8981\u79F0\u5176\u9760\u8FD1\u4E2D\u5EAD\u4E0E\u9E70\u820D\u3002"),e("Its exact position and use.","\u786E\u5207\u4F4D\u7F6E\u4E0E\u7528\u9014\u3002"),e("Placed on the west side of the yards, near the mews.","\u7F6E\u4E8E\u5404\u9662\u843D\u897F\u4FA7\uFF0C\u9760\u8FD1\u9E70\u820D\u3002")),"wailing-tower":t(e("Wailing Tower","\u54C0\u568E\u5854"),e("A fire-cracked tower with storerooms at its foot and deep vaults beneath, where servants sleep.","\u88AB\u70C8\u706B\u70E7\u88C2\u7684\u5854\u697C\uFF0C\u5E95\u5C42\u662F\u50A8\u85CF\u5BA4\uFF0C\u5730\u4E0B\u662F\u5E7D\u6DF1\u7684\u5730\u7A96\uFF0C\u4EC6\u5F79\u4FBF\u7761\u5728\u90A3\u91CC\u3002"),e("The wind moaning through cracked stone gives the Wailing Tower its name.","\u98CE\u7A7F\u8FC7\u5F00\u88C2\u7684\u77F3\u7F1D\u545C\u54BD\u4F5C\u54CD\uFF0C\u54C0\u568E\u5854\u7531\u6B64\u5F97\u540D\u3002"),"medium",["acok","awoiaf"],e("A named tower with storerooms and vaults; Arya sleeps in a niche in those vaults.","\u4E00\u5EA7\u6709\u540D\u5B57\u7684\u5854\u697C\uFF0C\u8BBE\u6709\u50A8\u85CF\u5BA4\u4E0E\u5730\u7A96\uFF1B\u827E\u8389\u4E9A\u66FE\u7761\u5728\u5730\u7A96\u7684\u4E00\u5904\u58C1\u9F9B\u91CC\u3002"),e("Its position, its height and the true origin of its name.","\u4F4D\u7F6E\u3001\u9AD8\u5EA6\u53CA\u540D\u5B57\u7684\u771F\u6B63\u7531\u6765\u3002"),e("East of the great hall, with a cracked, slumped crown.","\u7F6E\u4E8E\u5927\u5385\u4E1C\u4FA7\uFF0C\u5854\u9876\u5F00\u88C2\u584C\u9677\u3002")),"kingspyre-tower":t(e("Kingspyre Tower","\u738B\u711A\u5854"),e("The tallest of the five towers, where Harren and his sons died in the dragonfire. The castellan's chambers are here.","\u4E94\u5854\u4E2D\u6700\u9AD8\u7684\u4E00\u5EA7\uFF0C\u9ED1\u5FC3\u8D6B\u4F26\u4E0E\u8BF8\u5B50\u846C\u8EAB\u9F99\u7130\u4E4B\u5904\u3002\u4EE3\u7406\u57CE\u4E3B\u7684\u5C45\u6240\u5C31\u5728\u5854\u4E2D\u3002"),e("Kingspyre, where Harren burned, is the tallest of the five.","\u738B\u711A\u5854\u662F\u8D6B\u4F26\u846C\u8EAB\u706B\u6D77\u4E4B\u5904\uFF0C\u4E5F\u662F\u4E94\u5854\u4E2D\u6700\u9AD8\u7684\u4E00\u5EA7\u3002"),"medium",["acok","twoiaf","awoiaf"],e("The largest and tallest tower, named for Harren's death by fire; it holds chambers spacious enough for a great lord.","\u6700\u5927\u6700\u9AD8\u7684\u5854\uFF0C\u56E0\u8D6B\u4F26\u846C\u8EAB\u706B\u6D77\u800C\u5F97\u540D\uFF1B\u5854\u5185\u5C45\u5BA4\u5BBD\u655E\uFF0C\u8DB3\u4EE5\u8BA9\u5927\u9886\u4E3B\u4E0B\u69BB\u3002"),e("Its dimensions and floor plan.","\u5177\u4F53\u5C3A\u5BF8\u4E0E\u697C\u5C42\u5E03\u5C40\u3002"),e("Drawn as the tallest drum, linked by a bridge to the Widow's Tower.","\u753B\u6210\u6700\u9AD8\u7684\u5706\u5854\uFF0C\u4EE5\u4E00\u5EA7\u6865\u4E0E\u5BE1\u5987\u5854\u76F8\u8FDE\u3002")),"tower-of-ghosts":t(e("Tower of Ghosts","\u9B3C\u5F71\u5854"),e("A ruinous tower near the postern gate in the east wall, beside the fallen sept.","\u4E1C\u5899\u8FB9\u95E8\u9644\u8FD1\u7684\u4E00\u5EA7\u6B8B\u5854\uFF0C\u65C1\u8FB9\u662F\u5012\u584C\u7684\u5723\u5802\u3002"),e("Cold, creaking and half forgotten: the Tower of Ghosts.","\u51B0\u51B7\u3001\u5431\u560E\u4F5C\u54CD\u3001\u51E0\u8FD1\u88AB\u4EBA\u9057\u5FD8\uFF1A\u8FD9\u5C31\u662F\u9B3C\u5F71\u5854\u3002"),"low",["acok","awoiaf"],e("One of the five named towers; reference summaries place it by the east postern and the collapsed sept.","\u4E94\u5EA7\u6709\u540D\u5B57\u7684\u5854\u697C\u4E4B\u4E00\uFF1B\u53C2\u8003\u6458\u8981\u79F0\u5176\u4F4D\u4E8E\u4E1C\u4FA7\u8FB9\u95E8\u4E0E\u5012\u584C\u7684\u5723\u5802\u65C1\u3002"),e("Its shape and use.","\u5F62\u5236\u4E0E\u7528\u9014\u3002"),e("Placed near the east wall; the haunted mood is atmosphere only.","\u7F6E\u4E8E\u4E1C\u5899\u9644\u8FD1\uFF1B\u95F9\u9B3C\u7684\u6C1B\u56F4\u4EC5\u4E3A\u6E32\u67D3\u3002")),"widows-tower":t(e("Widow's Tower","\u5BE1\u5987\u5854"),e("A tower joined to Kingspyre by a stone bridge, with a windowless dungeon vault beneath it.","\u4E00\u5EA7\u4EE5\u77F3\u6865\u4E0E\u738B\u711A\u5854\u76F8\u8FDE\u7684\u5854\u697C\uFF0C\u5854\u4E0B\u662F\u4E00\u95F4\u6CA1\u6709\u7A97\u6237\u7684\u5730\u7262\u3002"),e("A stone bridge links the Widow's Tower to Kingspyre; prisoners lie below.","\u4E00\u5EA7\u77F3\u6865\u628A\u5BE1\u5987\u5854\u4E0E\u738B\u711A\u5854\u76F8\u8FDE\uFF1B\u5854\u4E0B\u5173\u62BC\u7740\u56DA\u72AF\u3002"),"medium",["acok","asos","awoiaf"],e("A named tower with a great cell beneath it used for prisoners, linked to Kingspyre by a stone bridge.","\u4E00\u5EA7\u6709\u540D\u5B57\u7684\u5854\u697C\uFF0C\u5854\u4E0B\u5927\u7262\u7528\u6765\u5173\u62BC\u56DA\u72AF\uFF0C\u5E76\u6709\u77F3\u6865\u901A\u5F80\u738B\u711A\u5854\u3002"),e("Where it stands and what the bridge looks like.","\u6240\u5728\u4F4D\u7F6E\u53CA\u77F3\u6865\u7684\u6837\u5F0F\u3002"),e("A slimmer tower with a bridge to Kingspyre.","\u753B\u6210\u8F83\u7EA4\u7EC6\u7684\u5854\uFF0C\u6709\u6865\u901A\u5F80\u738B\u711A\u5854\u3002")),"hall-of-hundred-hearths":t(e("Hall of a Hundred Hearths","\u767E\u7089\u5385"),e("The largest hall in Westeros, its roof bristling with chimneys. Despite the name it has only some thirty-odd hearths. A cutaway shows the interior.","\u7EF4\u65AF\u7279\u6D1B\u6700\u5927\u7684\u5385\u5802\uFF0C\u5C4B\u9876\u70DF\u56F1\u6797\u7ACB\u3002\u540D\u4E3A\u767E\u7089\uFF0C\u5B9E\u9645\u53EA\u6709\u4E09\u5341\u591A\u5EA7\u58C1\u7089\u3002\u53EF\u6253\u5F00\u5256\u9762\u67E5\u770B\u5185\u90E8\u3002"),e("Built to feast an army; today most of its hearths stand cold.","\u6B64\u5385\u672C\u4E3A\u5BB4\u98E8\u4E00\u652F\u5927\u519B\u800C\u5EFA\uFF0C\u5982\u4ECA\u5927\u534A\u58C1\u7089\u51B0\u51B7\u3002"),"high",["acok","awoiaf"],e("A vast hall with many hearths, mostly cold and empty; Arya counts thirty-three one time and thirty-five another.","\u4E00\u5EA7\u58C1\u7089\u4F17\u591A\u7684\u5DE8\u5385\uFF0C\u5927\u591A\u51B0\u51B7\u7A7A\u8361\uFF1B\u827E\u8389\u4E9A\u6570\u8FC7\u4E24\u6B21\uFF0C\u4E00\u6B21\u6570\u51FA\u4E09\u5341\u4E09\u5EA7\uFF0C\u4E00\u6B21\u4E09\u5341\u4E94\u5EA7\u3002"),e("Its roof structure and interior arrangement.","\u5C4B\u9876\u7ED3\u6784\u4E0E\u5185\u90E8\u5E03\u7F6E\u3002"),e("A long slate-roofed block with 34 chimneys; the interior is imagined.","\u4E00\u5EA7\u957F\u6761\u5F62\u77F3\u677F\u9876\u5EFA\u7B51\uFF0C\u7ACB\u7740\u4E09\u5341\u56DB\u6839\u70DF\u56F1\uFF1B\u5185\u90E8\u5E03\u7F6E\u7EAF\u5C5E\u60F3\u8C61\u3002")),godswood:t(e("Godswood","\u795E\u6728\u6797"),e("A walled wood of some twenty acres around a great weirwood, long neglected.","\u7EA6\u4E8C\u5341\u82F1\u4EA9\u7684\u56F4\u5899\u6797\u5730\uFF0C\u4E2D\u592E\u6709\u4E00\u682A\u5DE8\u5927\u7684\u9C7C\u6881\u6728\uFF0C\u4E45\u5DF2\u8352\u758F\u3002"),e("A great walled wood, left to the old gods and the crows.","\u4E00\u5927\u7247\u56F4\u5899\u73AF\u7ED5\u7684\u6797\u5730\uFF0C\u53EA\u7559\u7ED9\u65E7\u795E\u4E0E\u4E4C\u9E26\u3002"),"medium",["acok","awoiaf"],e("A large walled godswood with a heart tree; Arya prays there.","\u4E00\u5EA7\u56F4\u5899\u73AF\u7ED5\u7684\u5927\u795E\u6728\u6797\uFF0C\u5185\u6709\u5FC3\u6811\uFF1B\u827E\u8389\u4E9A\u66FE\u5728\u6B64\u7948\u7977\u3002"),e("Its exact area and position.","\u786E\u5207\u9762\u79EF\u4E0E\u4F4D\u7F6E\u3002"),e("Placed in the north-east; generic oaks plus one weirwood.","\u7F6E\u4E8E\u4E1C\u5317\uFF1B\u4EE5\u666E\u901A\u6A61\u6811\u52A0\u4E00\u682A\u9C7C\u6881\u6728\u8868\u73B0\u3002")),"walls-and-gate":t(e("Walls and Gate","\u57CE\u5899\u4E0E\u57CE\u95E8"),e("Immense curtain walls of fire-blackened stone with great towers; the castle covers more ground than any other in the realm.","\u70DF\u718F\u706B\u71CE\u7684\u5DE8\u77F3\u57CE\u5899\uFF0C\u914D\u4EE5\u96C4\u4F1F\u7684\u5854\u697C\uFF1B\u57CE\u5821\u5360\u5730\u4E4B\u5E7F\uFF0C\u51A0\u7EDD\u5168\u5883\u3002"),e("Even the walls are colossal; few garrisons could ever fill them.","\u57CE\u5899\u672C\u8EAB\u5C31\u5927\u5F97\u60CA\u4EBA\uFF0C\u9C9C\u6709\u5B88\u519B\u80FD\u628A\u5B83\u586B\u6EE1\u3002"),"medium",["acok","twoiaf"],e("Huge walls and towers, far larger than the households that have held it can man.","\u57CE\u5899\u4E0E\u5854\u697C\u89C4\u6A21\u5B8F\u5927\uFF0C\u5386\u6765\u9A7B\u5B88\u7684\u5BB6\u65CF\u90FD\u65E0\u529B\u5C06\u5176\u586B\u6EE1\u3002"),e("Height, thickness, and the number and shape of the gates.","\u57CE\u5899\u7684\u9AD8\u5EA6\u4E0E\u539A\u5EA6\uFF0C\u57CE\u95E8\u7684\u6570\u91CF\u4E0E\u5F62\u5236\u3002"),e("A fourteen-sided ring with two gatehouses; the real outline is unknown.","\u5341\u56DB\u8FB9\u5F62\u7684\u57CE\u5899\u52A0\u4E24\u5EA7\u95E8\u697C\uFF1B\u771F\u5B9E\u8F6E\u5ED3\u672A\u77E5\u3002")),"bear-pit":t(e("Bear Pit","\u718A\u5751"),e("A sunken stone pit where bears are baited for sport.","\u4E0B\u9677\u7684\u77F3\u780C\u6DF1\u5751\uFF0C\u7528\u6765\u6597\u718A\u53D6\u4E50\u3002"),e("A bear pit: sport for some, a death sentence for others.","\u718A\u5751\uFF1A\u5BF9\u4E00\u4E9B\u4EBA\u662F\u5A31\u4E50\uFF0C\u5BF9\u53E6\u4E00\u4E9B\u4EBA\u5374\u662F\u6B7B\u5211\u3002"),"medium",["asos"],e("Harrenhal has a bear pit, used in a scene of the third book.","\u8D6B\u4F26\u5821\u6709\u4E00\u5EA7\u718A\u5751\uFF0C\u7B2C\u4E09\u5377\u4E2D\u6709\u4E00\u5E55\u53D1\u751F\u5728\u8FD9\u91CC\u3002"),e("Its location and form.","\u4F4D\u7F6E\u4E0E\u5F62\u5236\u3002"),e("A round walled pit in the north-west.","\u7F6E\u4E8E\u897F\u5317\u7684\u4E00\u5EA7\u5706\u5F62\u56F4\u5751\u3002"),e("Brienne is thrown in with a bear, and Jaime leaps down to save her.","\u5E03\u857E\u59AE\u88AB\u4E22\u8FDB\u5751\u4E2D\u4E0E\u718A\u76F8\u640F\uFF0C\u8A79\u59C6\u7EB5\u8EAB\u8DF3\u4E0B\u6551\u5979\u3002")),baths:t(e("Baths","\u6D74\u573A"),e("A bathhouse whose great stone tubs steam with hot water.","\u4E00\u5EA7\u6D74\u5BA4\uFF0C\u5DE8\u5927\u7684\u77F3\u780C\u6D74\u6C60\u91CC\u70ED\u6C14\u84B8\u817E\u3002"),e("Even in a ruin, steam rises from the bathhouse.","\u5373\u4FBF\u5728\u5E9F\u589F\u4E4B\u4E2D\uFF0C\u6D74\u573A\u4ECD\u5192\u7740\u70ED\u6C14\u3002"),"low",["asos"],e("Harrenhal has baths, the setting of a scene in the third book.","\u8D6B\u4F26\u5821\u8BBE\u6709\u6D74\u573A\uFF0C\u7B2C\u4E09\u5377\u4E2D\u6709\u4E00\u5E55\u53D1\u751F\u4E8E\u6B64\u3002"),e("Everything about the building.","\u5EFA\u7B51\u672C\u8EAB\u7684\u4E00\u5207\u3002"),e("A low steaming house south of the hall.","\u5927\u5385\u5357\u4FA7\u4E00\u5EA7\u5192\u7740\u70ED\u6C14\u7684\u77EE\u5C4B\u3002")),"ruined-yards":t(e("Ruined Yards","\u8352\u5E9F\u5EAD\u9662"),e("Cobbled yards and broken buildings, far too many for the few who live here.","\u9E45\u5375\u77F3\u5EAD\u9662\u4E0E\u6B8B\u7834\u7684\u5C4B\u820D\uFF0C\u591A\u5F97\u8FDC\u975E\u5BE5\u5BE5\u4F4F\u6237\u6240\u80FD\u7528\u5C3D\u3002"),e("Only a fraction of Harrenhal is in use; the rest crumbles.","\u8D6B\u4F26\u5821\u53EA\u6709\u4E00\u5C0F\u90E8\u5206\u5728\u7528\uFF0C\u5176\u4F59\u90FD\u5728\u6162\u6162\u503E\u9893\u3002"),"medium",["acok","twoiaf"],e("Much of the castle stands unused or ruinous.","\u57CE\u5821\u5927\u534A\u7A7A\u7F6E\u6216\u5DF2\u6210\u5E9F\u589F\u3002"),e("Which parts are ruined.","\u5177\u4F53\u54EA\u4E9B\u90E8\u5206\u5DF2\u6210\u5E9F\u589F\u3002"),e("Rubble placed in the south-west.","\u6B8B\u57A3\u753B\u5728\u897F\u5357\u4E00\u5E26\u3002")),"god-s-eye":t(e("The God's Eye","\u795E\u773C\u6E56"),e("The great lake beside the castle, grey under grey skies.","\u57CE\u65C1\u7684\u5927\u6E56\uFF0C\u9634\u5929\u4E4B\u4E0B\u4E00\u7247\u7070\u8499\u3002"),e("The God's Eye spreads south of the walls, wide and quiet.","\u795E\u773C\u6E56\u5728\u57CE\u5899\u4EE5\u5357\u94FA\u5C55\u5F00\u53BB\uFF0C\u8FBD\u9614\u800C\u9759\u8C27\u3002"),"high",["acok","maps"],e("Harrenhal stands on the northern shore of the God's Eye.","\u8D6B\u4F26\u5821\u5750\u843D\u5728\u795E\u773C\u6E56\u5317\u5CB8\u3002"),e("How the castle meets the water.","\u57CE\u5821\u4E0E\u6E56\u5CB8\u5982\u4F55\u76F8\u63A5\u3002"),e("A jetty and a few fishing boats are invented.","\u6808\u6865\u4E0E\u51E0\u6761\u6E14\u8239\u4E3A\u81EA\u62DF\u3002"))}};export{w as default};
